  File.WriteAllText(Path.Combine(folder,"deck-picker-verification.txt"),"PASS: "+(checks-before)+" targeted deck selector assertions. Real WPF previews; loopback TCP="+VerificationRun.Network+"; no user data or clipboard writes.");
 }
 void VerifyStaleHandClick(){LeaveLan();localTest=true;match=MatchFixture();matchViewSeat=0;awaitHandoff=false;ShowPage("match");var unit=match.Summon(0,"VAN_CS2_182");unit.SummonTurn=0;ClearPending();RenderMatch();ClickMatchTarget(new MatchTarget(0,unit.Id));int card=Inject(match,"CS2_029");match.Players[0].Hand.RemoveAll(h=>h.Id==card);int mana=match.Players[0].Mana,hand=match.Players[0].Hand.Count;BeginCard(card);Check(status.Text.Contains("手牌已变化")&&pending=="attack"&&pendingId==unit.Id,"Stale hand click does not crash or cancel selected attacker");Check(match.Players[0].Mana==mana&&match.Players[0].Hand.Count==hand,"Stale hand click consumes no mana or cards");BeginCard(-123456);Check(pending=="attack","Repeated invalid hand clicks remain harmless");localTest=false;ClearPending();}
 void VerifyLegacyDeckTcp(string folder){LeaveLan();ApplyMode(false);var old=ExampleDeck("HUNTER");old.PoolId="classic-2014";var replace=old.Cards.First(p=>p.Value==2&&p.Key!="VAN_EX1_536");old.Cards.Remove(replace.Key);old.Cards["VAN_EX1_536"]=2;var saved=new SavedDeck{Id="old-hunter",Name="旧版猎人",PoolId=old.PoolId,Code=DeckCode.Encode(catalog,old)};savedDecks=new List<SavedDeck>{saved};string original=JsonData.Serializer().Serialize(saved);RefreshLanDecks();lanDeck.SelectedItem=((Choice[])lanDeck.ItemsSource).First(c=>c.Key==saved.Id);var current=DeckCode.Decode(catalog,DeckCode.Encode(catalog,ExampleDeck("MAGE")),"naxxramas-2014");var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{guest.draft=current;guest.RefreshLanDecks();guest.lanDeck.SelectedItem=((Choice[])guest.lanDeck.ItemsSource).First(c=>c.Key=="draft");lanPort.Text=FreeLanPort().ToString();BeginLan(true);guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Classic saved deck connects to current Naxx deck");Check(lanChosenDeck.PoolId==catalog.Pools.First(p=>!p.Archived).Id&&guest.lanChosenDeck.PoolId==catalog.Pools.First(p=>!p.Archived).Id,"Both lobby decks use active environment");var game=lanAuthority.Game;Check(game.Players[0].Deck.Concat(game.Players[0].Hand.Select(h=>h.CardId)).Count(id=>id=="NAX_EX1_536")==2,"Old Hunter bow resolves current era when match starts");Check(JsonData.Serializer().Serialize(saved)==original,"Starting LAN does not rewrite saved deck code or pool");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Legacy host mulligan reaches guest");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&guest.match.MulliganComplete,"Legacy/current deck pair completes mulligan");guest.LeaveLan();LeaveLan();BeginLan(true);guest.lanFingerprint="unused";guest.BeginLan(false);var parts=guest.lanFingerprint.Split(':');guest.lanFingerprint=parts[0]+":different-build";PumpLan(()=>guest.lanNotice.Text.Contains("程序构建版本不同"),"Same-version executable mismatch is clearly diagnosed over TCP");Check(!lanReady&&!guest.lanReady,"Build mismatch cannot start match");}finally{guest.LeaveLan();guest.Close();LeaveLan();}}

}
